// gparotationFixtures are the loading matrices the reference values were
// computed on.
func gparotationFixtures() map[string]*mat.Dense {
	return map[string]*mat.Dense{
		"twoBlocks":    twoBlocksLoadings(),
		"missingRows":  missingRowsLoadings(),
		"threeFactor":  loadings(),
		"overFactored": overFactoredStructure(),
	}
}

