// GPArotation's method names for the orthogonal and oblique engines.
var gparotationOrthogonal = map[string]string{"varimax": "varimax", "quartimax": "quartimax", "geominT": "geomin", "bentlerT": "bentler"}
var gparotationOblique = map[string]string{"quartimin": "quartimin", "oblimin": "oblimin", "geominQ": "geominQ", "bentlerQ": "bentlerQ", "simplimax": "simplimax"}

func TestGPARotationsFollowGPArotation(t *testing.T) {
	fixtures := gparotationFixtures()
	for _, c := range gparotationReference {
		name := c.fixture + "/" + c.method + "/" + c.start
		if c.normalize {
			name += "/normalized"
		}
		t.Run(name, func(t *testing.T) {
			A := mat.DenseCopyOf(fixtures[c.fixture])
			rows, k := A.Dims()
			T := identity(k)
			if c.start == "random" {
				T = mat.NewDense(k, k, gparotationRandomStarts[k])
			}
			var res map[string]any
			var err error
			if m, ok := gparotationOrthogonal[c.method]; ok {
				res, err = GPForth(A, T, c.normalize, 1e-5, 2000, m, c.param)
			} else {
				res, err = GPFoblq(A, T, c.normalize, 1e-5, 2000, gparotationOblique[c.method], c.param)
			}
			if err != nil {
				t.Fatal(err)
			}
			table := res["Table"].([][]float64)
			if len(table) < len(c.firstF) {
				t.Fatalf("stopped after %d iterations, GPArotation took %d", len(table)-1, c.iterations)
			}
			for i := range c.firstF {
				if d := math.Abs(table[i][1] - c.firstF[i]); d > 1e-10*math.Max(math.Abs(c.firstF[i]), 1e-12) {
					t.Errorf("iteration %d: criterion = %.15g, GPArotation has %.15g", i, table[i][1], c.firstF[i])
				}
				if d := math.Abs(table[i][3] - c.firstAlpha[i]); d > 1e-10*math.Abs(c.firstAlpha[i]) {
					t.Errorf("iteration %d: step size = %.15g, GPArotation has %.15g", i, table[i][3], c.firstAlpha[i])
				}
			}
			if got := res["convergence"].(bool); got != c.converged {
				t.Errorf("converged = %v after %d iterations, GPArotation reports %v after %d", got, len(table)-1, c.converged, c.iterations)
			}
			if !c.converged {
				// An unconverged run stops wherever its cap lands, and rounding
				// carried through 2000 steps moves that point.
				return
			}
			if f := res["f"].(float64); math.Abs(f-c.f) > 1e-8*math.Max(1, math.Abs(c.f)) {
				t.Errorf("criterion = %.12g, GPArotation reaches %.12g", f, c.f)
			}
			if d := maxAbsDiff(res["loadings"].(*mat.Dense), mat.NewDense(rows, k, c.loadings)); d > 1e-4 {
				t.Errorf("loadings differ from GPArotation by %.3e", d)
			}
		})
	}
}

// GPArotation's vgQ.simplimax(L, k) adds up exactly the k smallest squared
// loadings, taken in order(L^2), which breaks ties by column-major position,
// and GPArotation::simplimax defaults k to nrow(L) * (ncol(L) - 1). The values
// below are GPArotation:::vgQ.simplimax(L, k = k) from GPArotation 2026.8.2 on
// the fixtures above, at that default and at k = nrow(L). threeFactor repeats
// 0.10, 0.15 and 0.20, so its squared loadings tie at the k-th smallest.
type simplimaxCriterionCase struct {
	fixture string
	k       int
	f       float64
	gq      []float64
}

var simplimaxCriterionReference = []simplimaxCriterionCase{
	{fixture: "twoBlocks", k: 6, f: 0.0062689792897552866, gq: []float64{0, 0.072706668862253673, 0, -0.023906585010160054, 0, 0.034235215933208565, -0, -0.010276557446935486, -0, 0.12915633758908124, -0, -0.035484017145039071}},
	{fixture: "missingRows", k: 6, f: 0.01127734060258876, gq: []float64{-0, 0.094859295146571418, -0, 0.0042816706946864954, -0, 0.031295288109122563, 0, -0.001858519831500651, 0, 0.18104756640569825, 0, -0.04828740390091573}},
	{fixture: "threeFactor", k: 12, f: 0.24500000000000002, gq: []float64{0, 0.40000000000000002, 0.20000000000000001, 0, 0.29999999999999999, 0.10000000000000001, 0.20000000000000001, 0, 0.40000000000000002, 0.40000000000000002, 0, 0.29999999999999999, 0.10000000000000001, 0.29999999999999999, 0, 0.29999999999999999, 0.20000000000000001, 0}},
	{fixture: "threeFactor", k: 6, f: 0.057500000000000009, gq: []float64{0, 0, 0.20000000000000001, 0, 0, 0.10000000000000001, 0.20000000000000001, 0, 0, 0, 0, 0, 0.10000000000000001, 0, 0, 0.29999999999999999, 0.20000000000000001, 0}},
	{fixture: "overFactored", k: 18, f: 0.7579885456806843, gq: []float64{0, 0.015944265129155699, -0.028918973987661255, -0.43177046566308641, 0.48989084617983375, 0.79341914763798149, 0, -0.053723819045626856, 0.49237579646587376, 0, -0.36822806661357266, 0.21023874773664919, 0, -0.098048535396961553, 0.0097489011591967087, 0.42565222522772894, 0.50960325872327017, 0.80737606608398205, 0, -0.024842555982962873, 0.49111099268538205, 0, -0.41033498497435, 0.19286419072500857}},
	{fixture: "overFactored", k: 6, f: 0.0035756210837306875, gq: []float64{0, 0.015944265129155699, -0.028918973987661255, -0, 0, 0, 0, -0.053723819045626856, 0, 0, -0, 0, 0, -0.098048535396961553, 0.0097489011591967087, 0, 0, 0, 0, -0.024842555982962873, 0, 0, -0, 0}},
}

func TestSimplimaxCriterionFollowsGPArotation(t *testing.T) {
	fixtures := gparotationFixtures()
	for _, c := range simplimaxCriterionReference {
		L := fixtures[c.fixture]
		rows, cols := L.Dims()
		Gq, f, _ := vgQSimplimax(L, c.k)
		if math.Abs(f-c.f) > 1e-15 {
			t.Errorf("%s at k = %d: criterion = %.17g, GPArotation has %.17g", c.fixture, c.k, f, c.f)
		}
		if d := maxAbsDiff(Gq, mat.NewDense(rows, cols, c.gq)); d > 1e-15 {
			t.Errorf("%s at k = %d: gradient differs from GPArotation by %.3e", c.fixture, c.k, d)
		}
		if c.k != rows*(cols-1) {
			continue
		}
		got, err := Criterion("simplimax", L, 0, 0)
		if err != nil {
			t.Fatal(err)
		}
		if math.Abs(got-c.f) > 1e-15 {
			t.Errorf("%s: Criterion(\"simplimax\") = %.17g, GPArotation's default k = %d gives %.17g", c.fixture, got, c.k, c.f)
		}
	}
}
